create table if not exists public.ipc (
  mes date primary key check (extract(day from mes) = 1),
  indice numeric(10,2) not null check (indice > 0),
  var_homologa numeric(6,2),
  calculado boolean not null default false,
  fonte text not null default 'INE — IPCN (base Dez. 2020 = 100)'
);
comment on column public.ipc.calculado is 'true quando o índice foi obtido a partir da variação homóloga publicada (o INE ainda não publicou a tabela do ano).';
alter table public.ipc enable row level security;
create policy "leitura publica" on public.ipc for select to anon, authenticated using (true);
create policy "admin gere ipc" on public.ipc for all to authenticated using ((select privado.is_admin())) with check ((select privado.is_admin()));
