create table if not exists public.salario_minimo (
  id smallint generated by default as identity primary key,
  valor numeric(12,2) not null check (valor > 0),
  valido_desde date not null,
  valido_ate date,
  diploma text,
  nota text
);
alter table public.salario_minimo enable row level security;
create policy "leitura publica" on public.salario_minimo for select to anon, authenticated using (true);
create policy "admin gere salario_minimo" on public.salario_minimo for all to authenticated using ((select privado.is_admin())) with check ((select privado.is_admin()));
