-- Fim de validade exclusivo (como em vencimento_base: valido_ate > data).
create or replace function public.admin_ajuste_geral(p_numero text, p_titulo text, p_data_efeitos date, p_url text, p_valores jsonb, p_notas text default null)
returns integer language plpgsql security definer set search_path = '' as $$
declare d integer; k text; v numeric;
begin
  if not privado.is_admin() then raise exception 'Sem permissão' using errcode = '42501'; end if;
  if p_data_efeitos is null or coalesce(trim(p_numero), '') = '' then raise exception 'Indique o número do decreto e a data de efeitos'; end if;
  if exists (select 1 from public.diplomas where numero = trim(p_numero)) then raise exception 'Este decreto já está registado'; end if;
  insert into public.diplomas (tipo, numero, titulo, data_efeitos, url, notas)
  values ('ajuste_geral', trim(p_numero), coalesce(nullif(trim(p_titulo), ''), 'Ajustamento geral dos vencimentos'), p_data_efeitos, nullif(trim(p_url), ''), p_notas)
  returning id into d;
  for k, v in select key, value::numeric from jsonb_each_text(p_valores) loop
    if v is null or v <= 0 then continue; end if;
    if exists (select 1 from public.valores_indice_100 where grupo_id = k::int and valido_desde >= p_data_efeitos) then
      raise exception 'Já existe um valor para este grupo com data igual ou posterior';
    end if;
    update public.valores_indice_100 set valido_ate = p_data_efeitos
     where grupo_id = k::int and (valido_ate is null or valido_ate > p_data_efeitos);
    insert into public.valores_indice_100 (grupo_id, diploma_id, valor, valido_desde) values (k::int, d, round(v, 2), p_data_efeitos);
  end loop;
  return d;
end $$;
revoke all on function public.admin_ajuste_geral(text, text, date, text, jsonb, text) from public, anon;
grant execute on function public.admin_ajuste_geral(text, text, date, text, jsonb, text) to authenticated;
